/* ===== 工具函数 ===== */
const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const escapeHtml = (s) => String(s || '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const todayStr = () => new Date().toISOString().slice(0, 10);
const monthStr = () => new Date().toISOString().slice(0, 7);
const GOAL_BOARDS = ['达播', '页面', '推广', '活动', '会员', 'social', '直播', '设计', '其他'];
function goalBoardName(goal) { return String(goal && goal.board || '').trim() || '未分配板块'; }
function goalPeriod(goal) { return String(goal && goal.month || '').trim(); }
function isWeekGoal(goal) { return /^\d{4}-W\d{2}$/.test(goalPeriod(goal)) || String(goal && goal.id || '').startsWith('week_'); }
function groupGoalsByBoard(goals) {
  const groups = new Map();
  [...GOAL_BOARDS, '未分配板块'].forEach(board => groups.set(board, []));
  (goals || []).forEach(goal => groups.get(goalBoardName(goal)).push(goal));
  return [...groups.entries()].filter(([, items]) => items.length).map(([board, items]) => ({ board, goals: items }));
}
function dashboardGoalVisible(goal, selectedPeriod, currentPeriod) {
  if (!goal || goal.status === '__profile__') return false;
  if (selectedPeriod < currentPeriod) return true;
  if (goal.status === '已完成') return false;
  const range = goalTaskRange(goal);
  return !range || range.end >= todayStr();
}
function groupGoalsByPeriod(goals) {
  const periods = new Map();
  (goals || []).forEach(goal => {
    const period = goalPeriod(goal) || '未设置时间';
    if (!periods.has(period)) periods.set(period, []);
    periods.get(period).push(goal);
  });
  return [...periods.entries()]
    .map(([period, periodGoals]) => ({ period, goals: periodGoals }))
    .sort((a, b) => a.period === '未设置时间' ? 1 : b.period === '未设置时间' ? -1 : b.period.localeCompare(a.period));
}
function taskGoalLinkVisible(goal, linkedGoalId, currentWeek, currentMonth, today) {
  if (!goal || goal.status === '__profile__') return false;
  if (linkedGoalId && String(goal.id) === String(linkedGoalId)) return true;
  if (goal.status === '已完成') return false;
  const period = goalPeriod(goal);
  if (isWeekGoal(goal) ? period < currentWeek : period !== currentMonth) return false;
  const range = goalTaskRange(goal);
  return !!range && range.end >= today;
}
function taskGoalOptionLabel(goal) {
  const period = goalPeriod(goal);
  const prefix = isWeekGoal(goal) ? `${period.slice(5)}周目标` : `${period}月目标`;
  return `【${prefix}】${goal && goal.name || ''}`;
}
function goalPeriodLabel(goal, type) { return type === 'week' ? `周次：${goal.month || '—'}` : `月份：${goal.month || '—'}`; }
function dashboardDateRange() {
  if (State.dashboardPeriod === 'day') return { start: State.selectedDate, end: State.selectedDate };
  const now = new Date(State.selectedDate + 'T12:00:00');
  if (State.dashboardPeriod === 'custom') return { start: State.dashboardCustomStart, end: State.dashboardCustomEnd };
  if (State.dashboardPeriod === 'month') {
    const start = new Date(now.getFullYear(), now.getMonth(), 1);
    const end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    return { start: start.toISOString().slice(0, 10), end: end.toISOString().slice(0, 10) };
  }
  const start = new Date(now); start.setDate(now.getDate() - ((now.getDay() + 6) % 7));
  const end = new Date(start); end.setDate(start.getDate() + 6);
  return { start: start.toISOString().slice(0, 10), end: end.toISOString().slice(0, 10) };
}
function itemDate(item) { return (item.task_date || item.date || item.due_date || item.completion_date || item.created_at || '').slice(0, 10); }
function inDashboardRange(item, range) { const d = itemDate(item); return !!d && d >= range.start && d <= range.end; }
function isoDate(d) { return new Date(d).toISOString().slice(0, 10); }
function goalTaskRange(goal) {
  if (!goal || !goal.month) return null;
  const week = String(goal.month).match(/^(\d{4})-W(\d{2})$/);
  if (week) {
    const jan4 = new Date(Date.UTC(Number(week[1]), 0, 4));
    const monday = new Date(jan4);
    monday.setUTCDate(jan4.getUTCDate() - ((jan4.getUTCDay() + 6) % 7) + (Number(week[2]) - 1) * 7);
    const sunday = new Date(monday); sunday.setUTCDate(monday.getUTCDate() + 6);
    return { start: isoDate(monday), end: isoDate(sunday) };
  }
  const month = String(goal.month).match(/^(\d{4})-(\d{2})$/);
  if (month) {
    const start = `${month[1]}-${month[2]}-01`;
    const end = isoDate(new Date(Date.UTC(Number(month[1]), Number(month[2]), 0)));
    return { start, end };
  }
  return null;
}
function shiftIsoWeek(week, delta) {
  const range = goalTaskRange({ month: week });
  if (!range) return getWeekStr();
  const date = new Date(range.start + 'T12:00:00');
  date.setDate(date.getDate() + Number(delta || 0) * 7);
  return getWeekStr(date);
}
function shiftMonth(month, delta) {
  const match = String(month || '').match(/^(\d{4})-(\d{2})$/);
  if (!match) return monthStr();
  const date = new Date(Number(match[1]), Number(match[2]) - 1 + Number(delta || 0), 1);
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
}
function taskCompletionDay(task) {
  if (task.status !== '已完成') return '';
  return String(task.due_date || task.completion_date || task.task_date || task.date || '').slice(0, 10);
}
function taskOccursOn(task, date) {
  const ownDate = itemDate(task);
  // Linking a task must not remove it from the date explicitly chosen by the user.
  // The goal period adds recurring instances; it does not replace the original one.
  if (ownDate === date) return true;
  const goal = task.goal_id ? State.goals.find(g => String(g.id) === String(task.goal_id)) : null;
  if (!goal) return itemDate(task) === date;
  const goalRange = goalTaskRange(goal);
  if (!goalRange) return itemDate(task) === date;
  // A linked task becomes active immediately, even when its goal period is in the future.
  // There is no separate linked_at field yet, so created_at is the stable start point.
  const start = String(task.created_at || task.task_date || task.date || goalRange.start).slice(0, 10);
  const completed = taskCompletionDay(task);
  const end = completed && completed < goalRange.end ? completed : goalRange.end;
  return date >= start && date <= end;
}
function expandTasksForRange(source, range) {
  const instances = [];
  const cursor = new Date(range.start + 'T12:00:00');
  const end = new Date(range.end + 'T12:00:00');
  while (cursor <= end) {
    const date = isoDate(cursor);
    source.forEach(task => {
      if (!taskOccursOn(task, date)) return;
      const completionDay = taskCompletionDay(task);
      const beforeCompletion = completionDay && date < completionDay;
      instances.push({ ...task, _instance_date: date, task_date: date, status: beforeCompletion ? '进行中' : task.status, completion_rate: beforeCompletion ? 0 : task.completion_rate });
    });
    cursor.setDate(cursor.getDate() + 1);
  }
  return instances;
}
function actualTaskDuration(task) {
  if (task.status !== '已完成' || !task.created_at) return '';
  const completedAt = task.due_date || task.completion_date;
  if (!completedAt) return '';
  const start = new Date(task.created_at).getTime();
  const end = new Date(completedAt.length === 10 ? completedAt + 'T23:59:59' : completedAt).getTime();
  if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) return '';
  const minutes = Math.round((end - start) / 60000);
  if (minutes < 60) return `${minutes}分钟`;
  const hours = Math.floor(minutes / 60), mins = minutes % 60;
  return hours < 24 ? `${hours}小时${mins ? mins + '分钟' : ''}` : `${Math.floor(hours / 24)}天${hours % 24 ? hours % 24 + '小时' : ''}`;
}

