/* ===== 每日待办（月 → 周 → 日）===== */
function taskCalendarInstances() {
  if (!State.tasks.length) return [];
  const bounds = State.tasks.flatMap(task => {
    const own = itemDate(task);
    const goal = task.goal_id ? State.goals.find(g => String(g.id) === String(task.goal_id)) : null;
    const goalRange = goalTaskRange(goal);
    const start = goalRange ? String(task.created_at || own || goalRange.start).slice(0, 10) : own;
    const completed = taskCompletionDay(task);
    const end = goalRange ? (completed && completed < goalRange.end ? completed : goalRange.end) : own;
    return [start, end].filter(Boolean);
  });
  if (!bounds.length) return [];
  bounds.sort();
  return expandTasksForRange(State.tasks, { start: bounds[0], end: bounds[bounds.length - 1] });
}

function groupTasksByCalendar(tasks) {
  const months = new Map();
  tasks.forEach(task => {
    const date = task._instance_date || itemDate(task);
    if (!date) return;
    const monthKey = date.slice(0, 7);
    const weekKey = getWeekStr(new Date(date + 'T12:00:00'));
    if (!months.has(monthKey)) months.set(monthKey, new Map());
    const weeks = months.get(monthKey);
    if (!weeks.has(weekKey)) weeks.set(weekKey, new Map());
    const days = weeks.get(weekKey);
    if (!days.has(date)) days.set(date, []);
    days.get(date).push(task);
  });
  return [...months.entries()].sort(([a], [b]) => b.localeCompare(a)).map(([month, weeks]) => ({
    month,
    weeks: [...weeks.entries()].sort(([a], [b]) => b.localeCompare(a)).map(([week, days]) => ({
      week,
      days: [...days.entries()].sort(([a], [b]) => b.localeCompare(a)).map(([date, items]) => ({ date, items }))
    }))
  }));
}

function filterTasksByOwner(tasks, owner) {
  return owner ? tasks.filter(task => task.owner === owner) : tasks;
}

function renderTasks() {
  const statusMap = { '未开始':'badge-todo','进行中':'badge-doing','审核中':'badge-review','待上线':'badge-release','已完成':'badge-done','打白工':'badge-blocked' };
  const owners = [...new Set(State.tasks.map(task => task.owner).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'zh-CN'));
  const selectedOwner = owners.includes(State.taskOwnerFilter) ? State.taskOwnerFilter : '';
  const groups = groupTasksByCalendar(filterTasksByOwner(taskCalendarInstances(), selectedOwner));
  const ownerFilter = owners.length > 5
    ? `<label class="daily-owner-select-label">查看成员<select class="form-select" id="dailyOwnerFilter"><option value="">全部成员</option>${owners.map(owner => `<option value="${escapeHtml(owner)}" ${selectedOwner === owner ? 'selected' : ''}>${escapeHtml(owner)}</option>`).join('')}</select></label>`
    : `<div class="daily-owner-filter" aria-label="成员筛选"><button class="daily-owner-chip ${selectedOwner ? '' : 'active'}" data-action="task-owner-filter" data-id="">全部成员</button>${owners.map(owner => `<button class="daily-owner-chip ${selectedOwner === owner ? 'active' : ''}" data-action="task-owner-filter" data-id="${escapeHtml(owner)}">${escapeHtml(owner)}</button>`).join('')}</div>`;
  const monthHtml = groups.map(monthGroup => {
    const monthTasks = monthGroup.weeks.flatMap(w => w.days.flatMap(d => d.items));
    const monthDone = monthTasks.filter(t => t.status === '已完成').length;
    const monthRate = monthTasks.length ? Math.round(monthDone / monthTasks.length * 100) : 0;
    const [year, month] = monthGroup.month.split('-');
    const weeksHtml = monthGroup.weeks.map(weekGroup => {
      const range = goalTaskRange({ month: weekGroup.week });
      const weekCount = weekGroup.days.reduce((sum, day) => sum + day.items.length, 0);
      const weekNumber = Number(weekGroup.week.slice(-2));
      const daysHtml = weekGroup.days.map(dayGroup => {
        const done = dayGroup.items.filter(t => t.status === '已完成').length;
        const rate = dayGroup.items.length ? Math.round(done / dayGroup.items.length * 100) : 0;
        const dateObj = new Date(dayGroup.date + 'T12:00:00');
        const weekDays = ['周日','周一','周二','周三','周四','周五','周六'];
        const taskRows = dayGroup.items.map(t => `<li class="daily-calendar-task" data-action="edit-task" data-id="${t.id}" title="点击编辑">
          <span class="badge ${statusMap[t.status] || 'badge-todo'}">${escapeHtml(t.status)}</span>
          <span class="daily-calendar-task-name">${escapeHtml(t.content)}</span>
          <span class="daily-calendar-owner">${escapeHtml(t.owner || '未分配')}</span>
          <span class="daily-calendar-hours">${t.estimated_hours || 0}h</span>
          <button class="daily-calendar-delete" data-action="del-task" data-id="${t.id}" title="删除">×</button>
        </li>`).join('');
        return `<article class="daily-calendar-day">
          <div class="daily-calendar-day-head">
            <div class="daily-calendar-date">${dayGroup.date.slice(8, 10)}</div>
            <div class="daily-calendar-day-copy"><strong>${Number(dayGroup.date.slice(5, 7))}月${Number(dayGroup.date.slice(8, 10))}日 · ${weekDays[dateObj.getDay()]}</strong><span>当日 ${dayGroup.items.length} · 完成 ${done}</span></div>
            <div class="daily-calendar-rate">${rate}%</div>
          </div>
          <div class="owner-progress"><div class="owner-progress-fill" style="width:${rate}%"></div></div>
          <ul class="daily-calendar-task-list">${taskRows}</ul>
        </article>`;
      }).join('');
      return `<section class="daily-calendar-week">
        <div class="daily-calendar-week-head"><strong><span></span>第${weekNumber}周</strong><small>${range ? `${range.start.slice(5)} 至 ${range.end.slice(5)}` : weekGroup.week} · ${weekCount} 条待办</small></div>
        <div class="daily-calendar-days">${daysHtml}</div>
      </section>`;
    }).join('');
    return `<section class="daily-calendar-month">
      <div class="daily-calendar-month-head"><div><span class="daily-calendar-month-tag">${monthGroup.month === monthStr() ? '本月' : '月份'}</span><strong>${year}年${Number(month)}月</strong></div><small>共 ${monthTasks.length} 条 · 完成 ${monthDone} · ${monthRate}%</small></div>
      ${weeksHtml}
    </section>`;
  }).join('');

  return `<div class="daily-task-toolbar"><div><span class="card-title">每日待办</span>${ownerFilter}</div><button class="btn btn-primary" data-action="add-task">+ 添加待办</button></div>
    ${monthHtml || `<div class="empty-state"><div class="empty-state-icon">${ico('list')}</div>暂无待办，点击右上角添加</div>`}`;
}

