/* ===== 事件绑定 ===== */
function bindActions() {
  // 通过 data-action 委托
  document.querySelectorAll('[data-action]').forEach(el => {
    const trigger = () => handleAction(el.dataset.action, el.dataset.id, el);
    if (el.matches('input,select')) el.onchange = trigger;
    else el.onclick = trigger;
  });
  const wdHistory = document.getElementById('wd-history');
  if (wdHistory) wdHistory.onchange = () => { if (wdHistory.value) { State.selectedWorkDivision = wdHistory.value; render(); } };
  const onlineLinkSearch = document.getElementById('onlineLinkSearch');
  if (onlineLinkSearch) {
    onlineLinkSearch.oninput = () => { State.onlineLinkSearch = onlineLinkSearch.value; applyOnlineLinkSearchFilter(); };
    applyOnlineLinkSearchFilter();
  }
  const dailyOwnerFilter = document.getElementById('dailyOwnerFilter');
  if (dailyOwnerFilter) dailyOwnerFilter.onchange = () => {
    State.taskOwnerFilter = dailyOwnerFilter.value;
    localStorage.setItem('wb_task_owner_filter', State.taskOwnerFilter);
    render();
  };
  document.querySelectorAll('[data-wd-select]').forEach(cell => {
    cell.onclick = (e) => { if (e.target.matches('input,textarea,button,select')) return; const [r,c]=cell.dataset.wdSelect.split(',').map(Number); const key= e.ctrlKey || e.metaKey; if(!key) State.workDivisionSelection=[]; const exists=State.workDivisionSelection.some(x=>x[0]===r&&x[1]===c); State.workDivisionSelection=exists?State.workDivisionSelection.filter(x=>x[0]!==r||x[1]!==c):[...State.workDivisionSelection,[r,c]]; render(); };
  });

  // 日期选择器
  const dashDate = document.getElementById('dashDate');
  if (dashDate) {
    dashDate.onchange = () => {
      State.selectedDate = dashDate.value || todayStr();
      State.dashboardPeriod = 'day';
      render();
    };
  }

  const modal = document.getElementById('modal');
  const taskModal = document.querySelector('[data-task-modal]');
  modal.onkeydown = (e) => {
    if (e.key === 'Escape') { e.preventDefault(); closeModal(); return; }
    if (!taskModal || e.key !== 'Enter') return;
    if (e.target.tagName === 'TEXTAREA' && !e.ctrlKey && !e.metaKey) return;
    e.preventDefault();
    document.getElementById('taskSaveButton')?.click();
  };

  // 看板拖拽
  setupKanbanDrag();
  setupGoalCarouselDrag();
}

function setupGoalCarouselDrag() {
  const viewport = document.querySelector('.dashboard-goal-viewport');
  if (!viewport) return;
  let startX = null;
  let pointerId = null;
  viewport.onpointerdown = (e) => {
    if (e.target.closest('button,[data-action]')) return;
    startX = e.clientX;
    pointerId = e.pointerId;
    viewport.setPointerCapture?.(e.pointerId);
  };
  viewport.onpointerup = (e) => {
    if (startX === null || e.pointerId !== pointerId) return;
    const delta = e.clientX - startX;
    startX = null;
    pointerId = null;
    if (Math.abs(delta) < 45) return;
    State.dashboardGoalSlide = delta < 0 ? 'month' : 'week';
    localStorage.setItem('wb_dashboard_goal_slide', State.dashboardGoalSlide);
    render();
  };
  viewport.onpointercancel = () => { startX = null; pointerId = null; };
}

function setupKanbanDrag() {
  const tasks = document.querySelectorAll('.kanban-task');
  const columns = document.querySelectorAll('.kanban-column');
  let draggedId = null;

  tasks.forEach(t => {
    t.addEventListener('dragstart', (e) => {
      draggedId = e.target.dataset.id;
      e.target.style.opacity = '0.5';
    });
    t.addEventListener('dragend', (e) => {
      e.target.style.opacity = '';
    });
  });
  columns.forEach(col => {
    col.addEventListener('dragover', (e) => { e.preventDefault(); col.style.background = '#eff6ff'; });
    col.addEventListener('dragleave', () => { col.style.background = ''; });
    col.addEventListener('drop', async (e) => {
      e.preventDefault();
      col.style.background = '';
      if (!draggedId) return;
      const newStatus = col.dataset.status;
      const currentTask = State.tasks.find(task => task.id === draggedId);
      const update = { status: newStatus, completion_rate: completionRateForStatus(newStatus, currentTask?.completion_rate) };
      await DB.updateTask(draggedId, update);
      draggedId = null;
      await DB.refresh();
      showToast('状态已更新');
    });
  });
}

async function handleAction(action, id, el) {
  switch (action) {
    case 'dashboard-period':
      State.dashboardPeriod=id;
      render();
      break;
    case 'dashboard-goal-slide':
      State.dashboardGoalSlide = id === 'month' ? 'month' : 'week';
      localStorage.setItem('wb_dashboard_goal_slide', State.dashboardGoalSlide);
      render();
      break;
    case 'dashboard-week-change':
      State.dashboardWeek = el.value || getWeekStr();
      localStorage.setItem('wb_dashboard_week', State.dashboardWeek);
      render();
      break;
    case 'dashboard-week-shift':
      State.dashboardWeek = shiftIsoWeek(State.dashboardWeek, Number(id));
      localStorage.setItem('wb_dashboard_week', State.dashboardWeek);
      render();
      break;
    case 'dashboard-week-current':
      State.dashboardWeek = getWeekStr();
      localStorage.setItem('wb_dashboard_week', State.dashboardWeek);
      render();
      break;
    case 'dashboard-month-change':
      State.dashboardMonth = el.value || monthStr();
      localStorage.setItem('wb_dashboard_month', State.dashboardMonth);
      render();
      break;
    case 'dashboard-month-shift':
      State.dashboardMonth = shiftMonth(State.dashboardMonth, Number(id));
      localStorage.setItem('wb_dashboard_month', State.dashboardMonth);
      render();
      break;
    case 'dashboard-month-current':
      State.dashboardMonth = monthStr();
      localStorage.setItem('wb_dashboard_month', State.dashboardMonth);
      render();
      break;
    case 'task-owner-filter':
      State.taskOwnerFilter = id || '';
      localStorage.setItem('wb_task_owner_filter', State.taskOwnerFilter);
      render();
      break;
    case 'dashboard-custom': {
      showModal(
        '<div class="modal-title">自定义数据范围</div>' +
        '<div class="form-group"><label class="form-label">开始日期</label><input class="form-input" type="date" id="dashboardRangeStart" value="' + State.dashboardCustomStart + '"></div>' +
        '<div class="form-group"><label class="form-label">结束日期</label><input class="form-input" type="date" id="dashboardRangeEnd" value="' + State.dashboardCustomEnd + '"></div>' +
        '<div class="modal-actions"><button class="btn btn-secondary" onclick="closeModal()">取消</button><button class="btn btn-primary" data-action="dashboard-custom-apply">查看数据</button></div>'
      );
      bindActions();
      break;
    }
    case 'dashboard-custom-apply': {
      const start=document.getElementById('dashboardRangeStart').value;
      const end=document.getElementById('dashboardRangeEnd').value;
      if (!start || !end) { showToast('请选择开始和结束日期'); break; }
      if (end < start) { showToast('结束日期不能早于开始日期'); break; }
      State.dashboardCustomStart=start;
      State.dashboardCustomEnd=end;
      if (start === end) State.selectedDate=start;
      State.dashboardPeriod='custom';
      closeModal(); render(); break;
    }
    case 'online-link-add':
      onlineLinkModal();
      break;
    case 'online-link-filter':
      State.onlineLinkCategory = id || '全部';
      render();
      break;
    case 'online-link-pin-category':
    case 'online-link-unpin-category': {
      const category = action === 'online-link-pin-category' ? id : '';
      try {
        await DB.savePinnedOnlineLinkCategory(category);
        applyOnlineSheetLinkRows(await DB.loadOnlineSheetLinks());
        render(); showToast(category ? `“${category}”板块已置顶` : '已取消板块置顶');
      } catch (error) { showToast(onlineSheetLinkErrorMessage(error)); }
      break;
    }
    case 'online-link-edit': {
      const link = State.onlineSheetLinks.find(item => item.id === id);
      if (link) onlineLinkModal(link);
      break;
    }
    case 'online-link-save': {
      const title = document.getElementById('onlineLinkTitle').value.trim();
      const category = document.getElementById('onlineLinkCategory').value.trim();
      const url = normalizeOnlineLinkUrl(document.getElementById('onlineLinkUrl').value);
      if (!title) { showToast('请填写在线表名称'); break; }
      if (!category) { showToast('请选择分类'); break; }
      if (!url) { showToast('请填写有效的 http 或 https 链接'); break; }
      const data = {
        title, category, url,
        description: document.getElementById('onlineLinkDescription').value.trim(),
        owner: document.getElementById('onlineLinkOwner').value.trim() || State.currentUser || '',
        sort_order: Number(document.getElementById('onlineLinkSort').value || 0),
      };
      try {
        if (id) await DB.updateOnlineSheetLink(id, data);
        else await DB.saveOnlineSheetLink({ id: uid(), ...data });
        applyOnlineSheetLinkRows(await DB.loadOnlineSheetLinks());
        closeModal(); render(); showToast('在线表链接已保存并同步');
      } catch (error) {
        showToast(onlineSheetLinkErrorMessage(error));
      }
      break;
    }
    case 'online-link-delete': {
      if (!confirm('确认删除这个在线表链接？所有用户都将看不到它。')) break;
      try {
        await DB.deleteOnlineSheetLink(id);
        applyOnlineSheetLinkRows(await DB.loadOnlineSheetLinks());
        render(); showToast('在线表链接已删除');
      } catch (error) { showToast('删除失败：' + error.message); }
      break;
    }
    case 'wd-edit-row': {
      const d=currentWorkDivision(), row=Number(id), r=d.rows[row] || ['', '', '', ''];
      showModal(
        '<div class="modal-title">编辑第 ' + (row + 1) + ' 条分工</div>' +
        '<div class="form-group"><label class="form-label">板块</label><input class="form-input" id="wd-row-section" value="' + escapeHtml(r[0] || '') + '"></div>' +
        '<div class="form-group"><label class="form-label">需求</label><input class="form-input" id="wd-row-requirement" value="' + escapeHtml(r[1] || '') + '"></div>' +
        '<div class="form-group"><label class="form-label">负责人</label><input class="form-input" id="wd-row-owner" value="' + escapeHtml(r[2] || '') + '"></div>' +
        '<div class="form-group"><label class="form-label">备注</label><textarea class="form-textarea" id="wd-row-note">' + escapeHtml(r[3] || '') + '</textarea></div>' +
        '<div class="modal-actions"><button class="btn btn-secondary" onclick="closeModal()">取消</button><button class="btn btn-primary" data-action="wd-save-row" data-id="' + row + '">保存</button></div>'
      );
      bindActions();
      break;
    }
    case 'wd-save-row': {
      const d=currentWorkDivision(), row=Number(id);
      if (!d.rows[row]) d.rows[row]=d.columns.map(() => '');
      d.rows[row][0]=document.getElementById('wd-row-section').value.trim();
      d.rows[row][1]=document.getElementById('wd-row-requirement').value.trim();
      d.rows[row][2]=document.getElementById('wd-row-owner').value.trim();
      d.rows[row][3]=document.getElementById('wd-row-note').value.trim();
      d.updated_at=new Date().toISOString();
      saveWorkDivisions(); closeModal(); render(); break;
    }
    case 'wd-cancel-edit': State.workDivisionEdit=false; State.workDivisionEditingRow=null; State.workDivisionSelection=[]; render(); break;
    case 'wd-save-edit': { const d=currentWorkDivision(); document.querySelectorAll('.wd-cell').forEach(input=>{d.rows[+input.dataset.wdRow][+input.dataset.wdCol]=input.value;}); saveWorkDivisions(); State.workDivisionEdit=false; State.workDivisionEditingRow=null; State.workDivisionSelection=[]; render(); break; }
    case 'wd-merge': { const d=currentWorkDivision(), s=State.workDivisionSelection; if(s.length<2){showToast('请先选择两个或以上单元格');break;} const rs=s.map(x=>x[0]), cs=s.map(x=>x[1]); const r0=Math.min(...rs),r1=Math.max(...rs),c0=Math.min(...cs),c1=Math.max(...cs); if(s.length!==(r1-r0+1)*(c1-c0+1)){showToast('只能合并连续矩形区域');break;} d.merges=d.merges||[]; d.merges.push({r:r0,c:c0,rowspan:r1-r0+1,colspan:c1-c0+1}); saveWorkDivisions(); showToast('已记录合并区域'); break; }
    case 'wd-unmerge': { const d=currentWorkDivision(), s=State.workDivisionSelection[0]; if(!s){showToast('请先选择合并区域');break;} d.merges=(d.merges||[]).filter(m=>!(s[0]>=m.r&&s[0]<m.r+m.rowspan&&s[1]>=m.c&&s[1]<m.c+m.colspan)); saveWorkDivisions(); showToast('已取消合并'); break; }
    case 'wd-save': {
      const d=currentWorkDivision(); d.title=document.getElementById('wd-title').value.trim()||d.title; d.start_date=document.getElementById('wd-start').value; d.end_date=document.getElementById('wd-end').value; d.notice=document.getElementById('wd-notice').value.trim();
      document.querySelectorAll('.wd-cell').forEach(input => { d.rows[Number(input.dataset.wdRow)][Number(input.dataset.wdCol)] = input.value; });
      d.updated_at=new Date().toISOString(); saveWorkDivisions(); showToast('工作分工已保存'); render(); break;
    }
    case 'wd-add-row': { const d=currentWorkDivision(); d.rows.push(d.columns.map(() => '')); render(); break; }
    case 'wd-delete-row': { const d=currentWorkDivision(); d.rows.splice(Number(id),1); saveWorkDivisions(); render(); break; }
    case 'wd-add-col': { const d=currentWorkDivision(); const name=prompt('请输入新列名称','新列'); if(name){d.columns.push(name);d.rows.forEach(r=>r.push(''));saveWorkDivisions();render();} break; }
    case 'wd-copy': { const d=currentWorkDivision(); const copy=JSON.parse(JSON.stringify(d)); copy.id='wd_'+Date.now(); copy.title=prompt('请输入新周期标题',d.title+'（复制）')||d.title+'（复制）'; copy.created_at=new Date().toISOString(); copy.updated_at=copy.created_at; State.workDivisions.unshift(copy); State.selectedWorkDivision=copy.id; saveWorkDivisions(); render(); break; }
    case 'wd-new': { const n=defaultWorkDivision(); n.id='wd_'+Date.now(); n.title=prompt('请输入新周期标题','新工作分工周期')||n.title; n.rows=[]; State.workDivisions.unshift(n); State.selectedWorkDivision=n.id; saveWorkDivisions(); render(); break; }
    // 导航
    case 'wd-delete-col': {
      const d = currentWorkDivision(), col = Number(id);
      if (d.columns.length <= 1) { showToast('至少保留一列'); break; }
      if (confirm('确认删除这一列？')) { d.columns.splice(col, 1); d.rows.forEach(r => r.splice(col, 1)); saveWorkDivisions(); render(); }
      break;
    }
    case 'wd-delete-division': {
      const d = currentWorkDivision(), row = Number(id);
      if (confirm('确认删除这条分工？')) { d.rows.splice(row, 1); d.updated_at = new Date().toISOString(); saveWorkDivisions(); render(); }
      break;
    }
    case 'nav':
      break;
    case 'nav-kanban':
      State.view = 'kanban';
      render();
      break;
    case 'nav-tasks':
      State.view = 'tasks';
      render();
      break;
    case 'nav-settings':
      State.view = 'settings';
      render();
      break;
    case 'filter-urgent':
      State.view = 'tasks';
      render();
      showToast('已切换到每日待办，请按优先级筛选');
      break;

    // 月目标
    case 'add-goal':
      if (el && el.dataset.context === 'dashboard') showGoalForm(null, State.dashboardMonth);
      else showGoalForm();
      break;
    case 'edit-goal': {
      const g = State.goals.find(x => x.id === id);
      if (g) showGoalForm(g);
      break;
    }
    case 'del-goal':
      if (confirm('确认删除该月目标？')) {
        await DB.deleteGoal(id);
        await DB.refresh();
        showToast('已删除');
      }
      break;
    case 'save-goal': {
      const name = document.getElementById('g_name').value.trim();
      if (!name) { showToast('请填写目标名称'); return; }
      const progress = parseInt(document.getElementById('g_progress').value) / 100;
      const data = {
        name,
        board: document.getElementById('g_board').value,
        owner: document.getElementById('g_owner').value.trim(),
        month: document.getElementById('g_month').value || monthStr(),
        priority: document.getElementById('g_priority').value,
        description: document.getElementById('g_desc').value.trim(),
        progress,
        status: document.getElementById('g_status').value,
        completion_date: document.getElementById('g_cdate').value || null,
      };
      // 状态与完成率联动：已完成 -> 100%
      if (data.status === '已完成' && data.progress < 1) data.progress = 1;
      try {
        let result;
        if (id) {
          result = await DB.updateGoal(id, data);
        } else {
          result = await DB.saveGoal({ id: uid(), ...data });
        }
        closeModal();
        await DB.refresh();
        showToast(result && result.cloudPersisted === false ? '云端 RLS 未放行，请先执行完整迁移 SQL；本次仅暂存本机' : result && result.boardPersisted === false ? '板块字段未被云端识别，请执行完整迁移 SQL 后重试' : '已保存');
      } catch (e) {
        showToast('保存失败: ' + e.message);
        console.error('save-goal error:', e);
      }
      break;
    }

    // 周目标
    case 'add-weekgoal':
      if (el && el.dataset.context === 'dashboard') showWeekGoalForm(null, State.dashboardWeek);
      else showWeekGoalForm();
      break;
    case 'edit-weekgoal': {
      const g = State.goals.find(x => x.id === id);
      if (g) showWeekGoalForm(g);
      break;
    }
    case 'del-weekgoal':
      if (confirm('确认删除该周目标？')) {
        await DB.deleteGoal(id);
        await DB.refresh();
        showToast('已删除');
      }
      break;
    case 'save-weekgoal': {
      const name = document.getElementById('g_name').value.trim();
      if (!name) { showToast('请填写目标名称'); return; }
      const progress = parseInt(document.getElementById('g_progress').value) / 100;
      const data = {
        name,
        board: document.getElementById('g_board').value,
        owner: document.getElementById('g_owner').value.trim(),
        month: document.getElementById('g_month').value || getWeekStr(),
        description: document.getElementById('g_desc').value.trim(),
        progress,
        status: document.getElementById('g_status').value,
        priority: document.getElementById('g_priority').value,
        completion_date: document.getElementById('g_cdate').value || null,
      };
      // 状态与完成率联动：已完成 -> 100%
      if (data.status === '已完成' && data.progress < 1) data.progress = 1;
      try {
        let result;
        if (id) {
          result = await DB.updateGoal(id, data);
        } else {
          result = await DB.saveGoal({ id: 'week_' + uid(), ...data });
        }
        closeModal();
        await DB.refresh();
        showToast(result && result.cloudPersisted === false ? '云端 RLS 未放行，请先执行完整迁移 SQL；本次仅暂存本机' : result && result.boardPersisted === false ? '板块字段未被云端识别，请执行完整迁移 SQL 后重试' : '已保存');
      } catch (e) {
        showToast('保存失败: ' + e.message);
        console.error('save-weekgoal error:', e);
      }
      break;
    }

    // 待办
    case 'add-task':
      showTaskForm();
      break;
    case 'prev-day': {
      const d = new Date(State.selectedDate);
      d.setDate(d.getDate() - 1);
      State.selectedDate = d.toISOString().slice(0, 10);
      State.dashboardPeriod = 'day';
      render();
      break;
    }
    case 'next-day': {
      const d = new Date(State.selectedDate);
      d.setDate(d.getDate() + 1);
      State.selectedDate = d.toISOString().slice(0, 10);
      State.dashboardPeriod = 'day';
      render();
      break;
    }
    case 'today':
      State.selectedDate = todayStr();
      State.dashboardPeriod = 'day';
      render();
      break;
    case 'edit-task': {
      const t = State.tasks.find(x => x.id === id);
      if (t) showTaskForm(t);
      break;
    }
    case 'del-task':
      if (confirm('确认删除该待办？')) {
        const del = State.tasks.find(x => x.id === id);
        const delGoalId = del ? (del.goal_id || null) : null;
        await DB.deleteTask(id);
        await DB.refresh();
        recalcGoalProgress(delGoalId);
        render();
        showToast('已删除');
      }
      break;
    case 'save-task': {
      const content = document.getElementById('t_content').value.trim();
      if (!content) { showToast('请填写工作内容'); return; }
      const existing = id ? State.tasks.find(x => x.id === id) : null;
      const status = document.getElementById('t_status').value;
      const rate = parseInt(document.getElementById('t_rate').value) / 100;
      const data = {
        content,
        description: document.getElementById('t_desc').value.trim(),
        owner: (existing && existing.owner) || State.currentUser,
        task_date: document.getElementById('t_date').value || todayStr(),
        status,
        estimated_hours: parseFloat(document.getElementById('t_hours').value) || 0,
        due_date: document.getElementById('t_cdate').value || null,
        priority: document.getElementById('t_priority').value,
        completion_rate: rate,
        goal_id: document.getElementById('t_goal').value || null,
      };
      // 手动完成率达到 100% 后锁定；否则按状态填入默认完成率。
      data.completion_rate = completionRateForStatus(status, data.completion_rate);
      if (status === '已完成') {
        const previousCompletion = existing && String(existing.due_date || existing.completion_date || '').includes('T')
          ? (existing.due_date || existing.completion_date) : '';
        data.due_date = previousCompletion || new Date().toISOString();
      }
      try {
        let oldGoalId = null;
        if (id) {
          oldGoalId = existing ? (existing.goal_id || null) : null;
          await DB.updateTask(id, data);
        } else {
          await DB.saveTask({ id: uid(), ...data });
        }
        closeModal();
        await DB.refresh();
        // 同步关联目标进度（编辑时旧目标 + 新目标都需重算）
        if (oldGoalId && oldGoalId !== data.goal_id) recalcGoalProgress(oldGoalId);
        recalcGoalProgress(data.goal_id);
        render();
        showToast('已保存');
      } catch (e) {
        showToast('保存失败: ' + e.message);
        console.error('save-task error:', e);
      }
      break;
    }

    // 设置
    case 'show-login':
      showLoginModal();
      break;
    case 'login': {
      const email = document.getElementById('login_email').value.trim();
      if (!email) { showToast('请输入邮箱'); return; }
      State.currentEmail = email;
      localStorage.setItem('wb_email', email);
      try {
        const profile = await DB.getProfile(email);
        if (profile) {
          State.currentUser = profile.name;
          localStorage.setItem('wb_currentUser', profile.name);
          closeModal();
          updateUserDisplay();
          render();
          showToast('欢迎回来，' + profile.name);
        } else {
          showNameSetup(email);
        }
      } catch (e) {
        closeModal();
        showToast('登录失败: ' + e.message);
      }
      break;
    }
    case 'save-name': {
      const name = document.getElementById('setup_name').value.trim();
      if (!name) { showToast('请输入名字'); return; }
      State.currentUser = name;
      localStorage.setItem('wb_currentUser', name);
      try { await DB.saveProfile(State.currentEmail, name); } catch (e) { console.error('saveProfile:', e); }
      closeModal();
      updateUserDisplay();
      render();
      showToast('设置成功');
      break;
    }
    case 'logout':
      localStorage.removeItem('wb_email');
      localStorage.removeItem('wb_currentUser');
      State.currentUser = '';
      State.currentEmail = '';
      render();
      showLoginModal();
      showToast('已退出登录');
      break;
    case 'save-user':
      State.currentUser = document.getElementById('set_user').value.trim();
      localStorage.setItem('wb_currentUser', State.currentUser);
      if (State.currentEmail) {
        try { await DB.saveProfile(State.currentEmail, State.currentUser); } catch (e) { console.error('saveProfile:', e); }
      }
      updateUserDisplay();
      showToast('名字已保存');
      break;
    case 'save-supabase': {
      const url = document.getElementById('set_sb_url').value.trim();
      const key = document.getElementById('set_sb_key').value.trim();
      if (!url || !key) { showToast('请填写完整'); return; }
      State.supabase = { url, key };
      localStorage.setItem('wb_supabase', JSON.stringify(State.supabase));
      closeModal();
      showToast('正在连接...');
      try {
        await DB.refresh();
        startPolling();
        render();
        showToast('已连接 Supabase，多人协同已启用');
      } catch (e) {
        showToast('连接失败: ' + e.message);
      }
      break;
    }
    case 'test-supabase':
      try {
        await DB._sbSelect('monthly_goals');
        await DB._sbSelect('online_sheet_links');
        await DB._cloudRequest('monthly_goals', 'list');
        showToast('Supabase 主库和 CloudBase 备份连接正常');
      } catch (e) {
        showToast('连接失败: ' + onlineSheetLinkErrorMessage(e));
      }
      break;
    case 'disconnect-supabase':
      State.supabase = null;
      localStorage.removeItem('wb_supabase');
      if (State.pollTimer) { clearInterval(State.pollTimer); State.pollTimer = null; }
      await DB.refresh();
      render();
      showToast('已切换到本地模式');
      break;
    case 'copy-sql': {
      const code = document.querySelector('.code-block').textContent;
      try {
        await navigator.clipboard.writeText(code);
        showToast('SQL 已复制');
      } catch {
        showToast('复制失败，请手动选择复制');
      }
      break;
    }
    case 'export-data': {
      const data = { goals: State.goals, tasks: State.tasks, exported_at: new Date().toISOString() };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `workboard-export-${todayStr()}.json`;
      a.click();
      URL.revokeObjectURL(url);
      showToast('已导出');
      break;
    }
    case 'clear-data':
      if (confirm('确认清空本地数据？此操作不可恢复。')) {
        localStorage.removeItem('wb_goals');
        localStorage.removeItem('wb_tasks');
        State.goals = [];
        State.tasks = [];
        render();
        showToast('已清空');
      }
      break;
  }
}

function updateUserDisplay() {
  const el = document.getElementById('currentUserDisplay');
  if (State.currentUser) {
    el.innerHTML = `<span style="margin-right:8px;font-weight:600;display:inline-flex;align-items:center;gap:6px">${ico('user')} ${escapeHtml(State.currentUser)}</span>`;
  } else {
    el.innerHTML = `<button class="btn btn-primary btn-sm" id="topbarLoginBtn" style="margin-right:8px">登录</button>`;
    const btn = document.getElementById('topbarLoginBtn');
    if (btn) btn.onclick = () => showLoginModal();
  }
}

/* ===== 导航切换 ===== */
document.querySelectorAll('.nav-item').forEach(tab => {
  tab.addEventListener('click', () => {
    State.view = tab.dataset.view;
    render();
  });
});

/* ===== 初始化 ===== */
async function init() {
  // 尝试自动登录（localStorage 里有邮箱则从 Supabase 拉名字）
  const savedEmail = localStorage.getItem('wb_email');
  if (savedEmail && DB.isOnline()) {
    try {
      const profile = await DB.getProfile(savedEmail);
      if (profile) {
        State.currentUser = profile.name;
        State.currentEmail = savedEmail;
        localStorage.setItem('wb_currentUser', profile.name);
      } else {
        State.currentEmail = savedEmail;
      }
    } catch (e) {
      // profiles 表可能还没建，静默
    }
  }

  updateUserDisplay();

  // 离线模式才加示例数据
  if (!DB.isOnline() && !localStorage.getItem('wb_goals') && !localStorage.getItem('wb_tasks')) {
    const sampleGoals = [
      { id: uid(), name: '8月销售目标达成', owner: State.currentUser || '张三', month: monthStr(), description: '月度销售额达到50万', progress: 0.6, status: '进行中', created_at: new Date().toISOString() },
      { id: uid(), name: '新产品V1.0上线', owner: '李四', month: monthStr(), description: '完成开发、测试与上线', progress: 0.8, status: '进行中', created_at: new Date().toISOString() },
      { id: uid(), name: '客户回访计划', owner: '王五', month: monthStr(), description: '回访Top20客户', progress: 1.0, status: '已完成', created_at: new Date().toISOString() },
    ];
    const sampleTasks = [
      { id: uid(), content: '跟进A客户签约', date: todayStr(), owner: State.currentUser || '张三', status: '进行中', estimated_hours: 2, completion_date: '', priority: '紧急', completion_rate: 0.5, goal_id: sampleGoals[0].id, created_at: new Date().toISOString() },
      { id: uid(), content: '准备周报数据汇总', date: todayStr(), owner: State.currentUser || '张三', status: '已完成', estimated_hours: 1, completion_date: todayStr(), priority: '高', completion_rate: 1.0, goal_id: sampleGoals[0].id, created_at: new Date().toISOString() },
      { id: uid(), content: '新产品核心功能测试', date: todayStr(), owner: '李四', status: '进行中', estimated_hours: 4, completion_date: '', priority: '高', completion_rate: 0.3, goal_id: sampleGoals[1].id, created_at: new Date().toISOString() },
      { id: uid(), content: '修复登录模块bug', date: todayStr(), owner: '李四', status: '已完成', estimated_hours: 1.5, completion_date: todayStr(), priority: '紧急', completion_rate: 1.0, goal_id: sampleGoals[1].id, created_at: new Date().toISOString() },
      { id: uid(), content: '整理Top20客户名单', date: todayStr(), owner: '王五', status: '未开始', estimated_hours: 2, completion_date: '', priority: '中', completion_rate: 0, goal_id: sampleGoals[2].id, created_at: new Date().toISOString() },
      { id: uid(), content: '发送客户回访邮件', date: todayStr(), owner: '王五', status: '进行中', estimated_hours: 3, completion_date: '', priority: '低', completion_rate: 0.4, goal_id: sampleGoals[2].id, created_at: new Date().toISOString() },
    ];
    localStorage.setItem('wb_goals', JSON.stringify(sampleGoals));
    localStorage.setItem('wb_tasks', JSON.stringify(sampleTasks));
  }

  await DB.refresh();
  if (DB.isOnline()) startPolling();

  // 未登录则弹出登录框
  if (!State.currentEmail) {
    showLoginModal();
  } else if (State.currentEmail && !State.currentUser) {
    showNameSetup(State.currentEmail);
  }
}

init();
